SELECT cf.id, cf.project_no, cf.title, cf.description, -- 关联查询图片：通过打样邀约的work_id获取图片 (SELECT file_url FROM sd_user_model_file WHERE id = CAST(inv.work_id AS UNSIGNED) ORDER BY crt_time DESC LIMIT 1) AS cover_image, cf.images, cf.video_url, cf.tags, cf.creator_user_id, cf.creator_name, cf.creator_avatar, cf.proofing_invitation_id, cf.manufacturer_user_id, cf.manufacturer_name, cf.manufacturer_avatar, cf.target_amount, cf.current_amount, cf.support_count, cf.view_count, cf.start_time, cf.end_time, cf.delivery_time, cf.status, cf.is_featured, cf.is_hot, cf.sort_order, cf.risk_tips, cf.draw_number, cf.total_samples, cf.draw_status, cf.draw_time, cf.manufacturer_photos, cf.manufacturer_upload_time, cf.escrow_status, cf.fund_release_time, cf.create_by, cf.create_time, cf.update_by, cf.update_time, -- 关联查询阶梯价格：从打样邀约中获取 inv.tiered_pricing FROM sd_crowdfunding_project cf LEFT JOIN sd_proofing_invitations inv ON cf.proofing_invitation_id = inv.id
AND cf.creator_user_id = #{userId}
AND cf.id IN ( SELECT DISTINCT project_id FROM sd_crowdfunding_support WHERE user_id = #{userId} AND order_no IS NOT NULL AND (status IS NULL OR status = 0) )
AND cf.manufacturer_user_id = #{userId}
AND 1 = 0
ORDER BY cf.create_time DESC




        AND project_no LIKE CONCAT('%', #{projectNo}, '%')


        AND title LIKE CONCAT('%', #{title}, '%')


        AND creator_user_id = #{creatorUserId}


        AND manufacturer_user_id = #{manufacturerUserId}


        AND status = #{status}


        AND is_featured = #{isFeatured}


        AND is_hot = #{isHot}


        AND start_time >= #{startTime}


        AND end_time <= #{endTime}


ORDER BY create_time DESC

