project_no = #{projectNo}, title = #{title}, description = #{description}, cover_image = #{coverImage}, images = #{images}, video_url = #{videoUrl}, tags = #{tags}, creator_user_id = #{creatorUserId}, creator_name = #{creatorName}, creator_avatar = #{creatorAvatar}, proofing_invitation_id = #{proofingInvitationId}, manufacturer_user_id = #{manufacturerUserId}, manufacturer_name = #{manufacturerName}, manufacturer_avatar = #{manufacturerAvatar}, target_amount = #{targetAmount}, current_amount = #{currentAmount}, support_count = #{supportCount}, view_count = #{viewCount}, start_time = #{startTime}, end_time = #{endTime}, delivery_time = #{deliveryTime}, status = #{status}, is_featured = #{isFeatured}, is_hot = #{isHot}, sort_order = #{sortOrder}, risk_tips = #{riskTips}, draw_number = #{drawNumber}, total_samples = #{totalSamples}, draw_status = #{drawStatus}, draw_time = #{drawTime}, manufacturer_photos = #{manufacturerPhotos}, manufacturer_upload_time = #{manufacturerUploadTime}, escrow_status = #{escrowStatus}, fund_release_audit_status = #{fundReleaseAuditStatus}, audit_remark = #{auditRemark}, audit_user_id = #{auditUserId}, audit_time = #{auditTime}, fund_release_time = #{fundReleaseTime}, tiered_pricing = #{tieredPricing}, profit_share_ratio = #{profitShareRatio}, update_by = #{updateBy}, update_time = #{updateTime},
